from collections import deque

def read_input():
    h, w = map(int, input().split())
    grid = [input() for _ in range(h)]
    return h, w, grid

def is_valid_char(c):
    return c.isalnum() or c == '?' or c == '!' or c == ',' or c == '.' or c == ' '

def find_images(grid):
    h, w = len(grid), len(grid[0])
    images = []

    def bfs(x, y):
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        queue = deque([(x, y)])
        image_chars = set()
        min_x, max_x, min_y, max_y = x, x, y, y

        while queue:
            cx, cy = queue.popleft()
            if not (0 <= cx < h and 0 <= cy < w and grid[cx][cy] == '+'):
                continue
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < h and 0 <= ny < w and grid[nx][ny].isalnum():
                    image_chars.add((nx, ny))
                    min_x, max_x = min(min_x, nx), max(max_x, nx)
                    min_y, max_y = min(min_y, ny), max(max_y, ny)
                    queue.append((nx, ny))

        if len(image_chars) > 9:  # At least 3x3 pixels including borders
            images.append((image_chars, min_x, max_x, min_y, max_y))

    for i in range(h):
        for j in range(w):
            if grid[i][j] == '+':
                bfs(i, j)

    return images

def process_ads(grid, images):
    h, w = len(grid), len(grid[0])
    banned_chars = {}

    for chars, _, _, _, _ in images:
        for cx, cy in chars:
            if not is_valid_char(grid[cx][cy]):
                banned_chars[(cx, cy)] = True

    for ((cx, cy), _) in banned_chars:
        size = float('inf')
        for chars, minX, maxX, minY, maxY in images:
            if (cx, cy) in chars:
                area = (maxX - minX + 1) * (maxY - minY + 1)
                if area < size:
                    size = area
                    min_image = (chars, minX, maxX, minY, maxY)
        for char in min_image[0]:
            grid[char[0]][char[1]] = ' '

    result = ''.join([''.join(row) for row in grid])
    return result

