def find_and_remove_ads(H, W, grid):
    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W

    def dfs(x, y, char, size):
        if not is_valid(x, y) or grid[x][y] != char or (x == 0 or y == 0 or x == H-1 or y == W-1):
            return False
        if size < 4:
            return True
        grid[x][y] = ' '
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dx, dy in directions:
            if not dfs(x + dx, y + dy, char, size - 1):
                return False
        return True

    for i in range(1, H-1):
        for j in range(1, W-1):
            if grid[i][j] == '+':
                valid = dfs(i, j, '+', 4)
                if valid:
                    size = 4
                    while dfs(i, j, '+', size):
                        size += 1
                    for k in range(size):
                        for l in range(size):
                            if is_valid(i-k, j-l):
                                grid[i-k][j-l] = ' '

    result = []
    for row in grid:
        result.append(''.join(row))

    return ''.join(result)

