            pixels.append((cx, cy))
            web_page[cx] = web_page[cx][:cy] + ' ' + web_page[cx][cy+1:]
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if (nx, ny) not in pixels:
                    stack.append((nx, ny))

    min_size = float('inf')
    for i in range(1, H-1):
        for j in range(1, W-1):
            if is_border_char(web_page[i][j]):
                pixels = []
                size = 0
                for cx in range(i, H-1):
                    for cy in range(j, W-1):
                        if is_border_char(web_page[cx][cy]):
                            dfs(cx, cy)
                            size += len([p for p in pixels if web_page[p[0]][p[1]] != ' '])
                            break
                    else:
                        continue
                    break
                if size > 0 and size < min_size:
                    min_size = size
                    min_pixels = pixels.copy()

    for px, py in min_pixels:
        web_page[px] = web_page[px][:py] + ' ' * len(min_pixels) + web_page[px][py+len(min_pixels):]

    return '\n'.join([''.join(line) for line in web_page])

