def remove_ads(height, width, webpage):
    def is_valid_char(char):
        return char.isalnum() or char in '?!., '

    def is_border(x, y):
        return webpage[x][y] == '+'

    def is_inside_image(x, y):
        return 1 <= x < height-1 and 1 <= y < width-1

    def is_banned_char_in_image(image):
        for i in range(1, len(image)-1):
            for j in range(1, len(image[i])-1):
                if not is_valid_char(image[i][j]):
                    return True
        return False

    def find_smallest_ad(images):
        min_area = float('inf')
        min_ad = None
        for image in images:
            area = len(image) * len(image[0])
            if area < min_area:
                min_area = area
                min_ad = image
        return min_ad

    def remove_ad(ad):
        for i in range(len(ad)):
            for j in range(len(ad[i])):
                webpage[i][j] = ' '

    def get_image(x, y):
        image = []
        stack = [(x, y)]
        visited = set()
        visited.add((x, y))
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while stack:
            cx, cy = stack.pop()
            row = []
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < height and 0 <= ny < width and not is_inside_image(nx, ny) and not (nx, ny) in visited and is_border(nx, ny):
                    visited.add((nx, ny))
                    stack.append((nx, ny))
                    row.extend(['+' for _ in range(width)])
                elif is_inside_image(nx, ny) and not (nx, ny) in visited and is_border(nx, ny):
                    visited.add((nx, ny))
                    stack.append((nx, ny))
                    row.extend([webpage[nx][ny]])
            image.append(row)
        return image

    images = []
    for i in range(height):
        for j in range(width):
            if is_border(i, j) and not (i, j) in visited:
                visited.add((i, j))
                images.append(get_image(i, j))

    ad_to_remove = find_smallest_ad(images)
    remove_ad(ad_to_remove)

    result = ''.join([''.join(line) for line in webpage])
    return result.strip()

