def remove_ads(height, width, web_page):
    def is_valid_image(image):
        if len(image) < 4 or len(image[0]) < 4:
            return False
        for row in image:
            if row[0] != '+' or row[-1] != '+':
                return False
        for i in range(1, len(image) - 1):
            if image[i][0] != '+' or image[i][-1] != '+':
                return False
            for j in range(1, len(image[i]) - 1):
                if image[i][j] not in '0123456789?!,.! ':
                    return False
        return True

    def get_images():
        images = []
        visited = [[False] * width for _ in range(height)]
        for y in range(height):
            for x in range(width):
                if not visited[y][x]:
                    if web_page[y][x] == '+':
                        image = []
                        queue = [(y, x)]
                        while queue:
                            cy, cx = queue.pop()
                            if visited[cy][cx]:
                                continue
                            visited[cy][cx] = True
                            image.append(web_page[cy][cx])
                            for ny, nx in ((cy-1, cx), (cy+1, cx), (cy, cx-1), (cy, cx+1)):
                                if 0 <= ny < height and 0 <= nx < width and not visited[ny][nx] and web_page[ny][nx] == '+':
                                    queue.append((ny, nx))
                        images.append(image)
        return images

    def remove_ad(ad):
        for cy, row in enumerate(ad):
            for cx, char in enumerate(row):
                if char != ' ':
                    web_page[cy + top_y][cx + left_x] = ' '

    images = get_images()
    for image in images:
        image_str = '\n'.join(''.join(row) for row in image)
        if is_valid_image(image):
            top_y = None
            left_x = None
            min_size = float('inf')
            for cy, row in enumerate(image):
                for cx, char in enumerate(row):
                    if char != '+':
                        size = sum(row.count('+') for row in image) - 4
                        if size < min_size:
                            min_size = size
                            top_y = cy
                            left_x = cx
            remove_ad(image)

    result = ''.join(''.join(row) for row in web_page)
    return result.replace('\n', '')

